"""Build honest offline report/HTML from an independently verified private output.
Never runs inference, fills missing metrics or changes experiment state.
"""
from pathlib import Path
from datetime import datetime,timezone
import argparse,json,html
DATA='https://drive.google.com/drive/folders/1DuH0YaEox08ZwzZDpRMOaFpMCeRyxiEF'
PAPER='https://arxiv.org/html/1911.03854v2'
ATTEMPT='OFFICIAL-6W-MM-USABLE-v2_seed42_20261027'
LABELS=['True','Satire/Parody','Misleading Content','Imposter Content','False Connection','Manipulated Content']
FIELDS=[('accuracy','Accuracy'),('micro_f1','Micro-F1'),('macro_f1','Macro-F1'),('weighted_f1','Weighted-F1'),('balanced_accuracy','Balanced accuracy'),('loss','Cross-entropy loss')]
def run(a):
 project=a.project.resolve();folder=a.run.resolve();r=json.loads(a.verification.read_text());assert r['status'].startswith('verified_saved_')
 assert folder.is_relative_to(project/'data/cloud_recovery');stamp=datetime.now(timezone.utc).isoformat();date=stamp[:10].replace('-','');best=r['selected'];epoch=best['epoch'];v=best['metrics'];t=r.get('test',{}).get('metrics');complete=bool(r['training_complete'] and r['test_verified'])
 name=('MULTIMODAL_FINAL_REPORT_' if complete else 'MM_PART2_STATUS_')+date;report=project/'results'/(name+'.md');page=project/'results'/(('UROP_Multimodal_Final_' if complete else 'UROP_Multimodal_Status_')+date+'.html')
 val_report=json.loads((folder/('validation_epoch%d_classification_report.json'%epoch)).read_text());test_report=json.loads((folder/'test_classification_report.json').read_text()) if t else None
 status='Scientific train/validation/test verified; final documentation/remote-backup acceptance must be checked separately.' if complete else 'PARTIAL Part2: final registered training and/or held-out testing remains unfinished.'
 def value(d,k):
  if not d:return 'Pending'
  return f'{100*d[k]:.4f}%' if k in ['accuracy','balanced_accuracy'] else f'{d[k]:.6f}'
 rows=['| Metric | Selected validation | Held-out public test | Paper validation | Paper test |','|---|---:|---:|---:|---:|']
 for k,label in FIELDS:rows+=['| '+label+' | '+value(v,k)+' | '+value(t,k)+' | '+('86.00%' if k=='accuracy' else 'Not reported')+' | '+('85.88%' if k=='accuracy' else 'Not reported')+' |']
 def classes(d):
  if not d:return 'Pending full held-out evaluation.'
  lines=['| Class | Precision | Recall | F1 | Support |','|---|---:|---:|---:|---:|']
  for lab in LABELS:q=d[lab];lines+=['| '+lab+' | '+' | '.join(f'{q[k]:.6f}' for k in ['precision','recall','f1-score'])+' | '+str(int(q['support']))+' |']
  return '\n'.join(lines)
 delta=(v['accuracy']-.86)*100;test_delta=(t['accuracy']-.8588)*100 if t else None
 comparison=f'Selected validation is {delta:+.4f} percentage points versus the paper’s86.00% reference. '+(f'Final test is {test_delta:+.4f} points versus85.88%; the +1-point test aspiration was '+('met.' if test_delta>=1 else 'not met.') if t else 'Final multimodal test is pending; no test improvement is claimed.')
 lines=['# Multimodal '+('verified scientific results' if complete else 'Part2 status'),'',stamp,'',status,'','## Protocol and completion',f'- Same seed42 experiment; accepted Part1 plus continuation. Validated epochs:{r["epochs_validated"]}; next epoch{r["next_epoch"]}, consumed cursor{r["cursor"]}, phase{r["phase"]}.',f'- Selected epoch:{epoch}; validation Macro-F1, then lower loss, then earlier epoch. Weights SHA256 `{best["weights_sha256"]}`.',f'- [Faculty dataset]({DATA}): usable563601train/59299validation/59270test; exactly491approved strict decode exclusions; official splits/labels unchanged.','- BERT-base selected text epoch4 warm start + ImageNetV2 ResNet50; both fine-tuned; independent512projections+LayerNorm; elementwise max;256GELU/dropout.2;6logits.','- Kaggle TeslaT4 device0, original frozen source/config/environment; same four-epoch schedule; no new seed/model/data.','','## Validation and test metrics','\n'.join(rows),'',comparison,'','## Class results: validation',classes(val_report),'','## Class results: held-out test',classes(test_report),'','## Interpretation and limitations','This is a numerical reference comparison, not a controlled paper reproduction or statistical superiority claim. The paper uses another feature/fine-tuning pipeline; one seed and extra text warm-start compute;335paper/release-row discrepancy;491class-skewed exclusions;3561cross-split image-byte hash groups. Dataset labels are weak supervision, not independent factual-truth verification. Paper Table6 error proportions are not class F1.','',f'Original source exports/private weights: `{folder.relative_to(project)}`. Independent readback: `{a.verification.resolve().relative_to(project)}`. Recovery proof: `'+json.dumps(r['recovery'])+'`.','',f'Paper: [{PAPER}]({PAPER}). Current cloud run/version and Git acceptance must be read from the latest Part2 receipts. No public/raw-data/weight publication is implied.']
 report.write_text('\n'.join(lines)+'\n')
 def table(headers,data):return '<table><thead><tr>'+''.join('<th>'+html.escape(x)+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+html.escape(str(x))+'</td>' for x in row)+'</tr>' for row in data)+'</tbody></table>'
 metric_table=table(['Metric','Validation','Public test','Paper val','Paper test'],[[label,value(v,k),value(t,k),'86.00%' if k=='accuracy' else 'Not reported','85.88%' if k=='accuracy' else 'Not reported'] for k,label in FIELDS])
 def ctable(d):return '<p>Pending.</p>' if not d else table(['Class','Precision','Recall','F1','Support'],[[lab,*[f'{d[lab][k]:.4f}' for k in ['precision','recall','f1-score']],int(d[lab]['support'])] for lab in LABELS])
 def confusion(prefix):
  p=folder/(prefix+'_confusions.json')
  if not p.exists():return '<p>Pending.</p>'
  d=json.loads(p.read_text());return table(['Actual / predicted',*LABELS],[[lab,*row] for lab,row in zip(LABELS,d['raw'])])
 architecture='''<svg viewBox="0 0 920 245" role="img" aria-label="Actual BERT and ResNet50 maximum-fusion architecture"><defs><marker id="a" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8" fill="#738097"/></marker></defs><g fill="none" stroke="#738097" stroke-width="1.6" marker-end="url(#a)"><path d="M145 65H175M365 65H395M145 175H175M365 175H395M555 65H575V120H605M555 175H575V120M725 120H755"/></g><g fill="#f5f7fb" stroke="#d8deea"><rect x="5" y="38" width="140" height="55" rx="8"/><rect x="175" y="38" width="190" height="55" rx="8"/><rect x="395" y="38" width="160" height="55" rx="8"/><rect x="5" y="148" width="140" height="55" rx="8"/><rect x="175" y="148" width="190" height="55" rx="8"/><rect x="395" y="148" width="160" height="55" rx="8"/><rect x="605" y="88" width="120" height="65" rx="8"/><rect x="755" y="80" width="160" height="82" rx="8"/></g><g fill="#23314a" text-anchor="middle" font-size="13" font-family="system-ui"><text x="75" y="61">Title → WordPiece</text><text x="75" y="80">max128 tokens</text><text x="270" y="61">BERT-base</text><text x="270" y="80">CLS768</text><text x="475" y="61">Linear768→512</text><text x="475" y="80">LayerNorm</text><text x="75" y="171">RGB image</text><text x="75" y="190">224×224</text><text x="270" y="171">ResNet50</text><text x="270" y="190">pooled2048</text><text x="475" y="171">Linear2048→512</text><text x="475" y="190">LayerNorm</text><text x="665" y="115">Elementwise</text><text x="665" y="135">maximum512</text><text x="835" y="104">Linear512→256</text><text x="835" y="123">GELU · dropout0.2</text><text x="835" y="144">Linear256→6</text></g></svg>'''
 css='body{font:15px/1.6 system-ui,sans-serif;color:#23314a;background:#fbfcfe;margin:0}main{max-width:1100px;margin:48px auto;padding:0 24px}h1{font-size:34px;letter-spacing:-1px}h2{margin-top:36px;font-size:20px}p{max-width:95ch}a{color:#2464eb}section{background:white;border:1px solid #e1e6ef;border-radius:12px;padding:24px;margin:20px 0;overflow:auto}table{border-collapse:collapse;width:100%;font-size:13px}th,td{text-align:left;border-bottom:1px solid #edf0f5;padding:10px}th{color:#617087;font-weight:600}.status{background:#edf3ff;padding:14px;border-radius:8px}.meta{color:#617087;font-size:13px}svg{width:100%;min-width:650px}'
 page.write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>UROP · Multimodal results</title><style>'+css+'</style><main><p class="meta">UROP · FAKEDDIT · SIX CLASSES</p><h1>Text + image classification</h1><p class="status">'+html.escape(status)+'</p><p><a href="'+DATA+'">Faculty dataset — original three TSV files</a> · Selected epoch '+str(epoch)+'</p><p class="meta">'+html.escape(stamp)+' · '+html.escape(ATTEMPT)+'</p><section><h2>Architecture</h2>'+architecture+'<p>Both encoders are fine-tuned. Text starts from the verified text-only epoch4 encoder; image starts from ImageNetV2.</p></section><section><h2>Validation and held-out test</h2>'+metric_table+'<p>'+html.escape(comparison)+'</p></section><section><h2>Six-class validation</h2>'+ctable(val_report)+'<h2>Six-class held-out test</h2>'+ctable(test_report)+'</section><section><h2>Validation confusion matrix</h2>'+confusion('validation_epoch'+str(epoch))+'<h2>Test confusion matrix</h2>'+confusion('test')+'</section><section><h2>Workflow</h2><p>Verify data and recovery → resume registered training → full validation after each epoch → freeze Macro-F1-selected checkpoint → one held-out test → independent prediction/metric verification → durable archives and Git backup.</p><h2>Comparison limits</h2><p>Different available-image cohort and fine-tuning pipeline; single seed; extra text warm-start training;491documented exclusions;335paper/release-row difference;3561cross-split byte-identical image groups. This is a benchmark-label classifier, not independent fact verification. <a href="'+PAPER+'">Original paper, Tables4–5</a>.</p></section></main></html>')
 print(json.dumps({'report':str(report),'html':str(page),'scientific_results_complete':complete,'backup_acceptance_separate':True}));return report,page
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--project',type=Path,required=True);p.add_argument('--run',type=Path,required=True);p.add_argument('--verification',type=Path,required=True);run(p.parse_args())
